-- TEST-only legacy published metadata without a primary link. The real native
-- save must restore the structural draft relationship without a parent change.
-- No published version, release approval or translation review is fabricated by
-- the repair. This regression's link postcondition is red on pre-455380 save.
begin;set local search_path=public,extensions;select no_plan();
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select('a3780000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','primary378-'||n||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,2)n;
insert into public.platform_user_roles(user_id,role_code)values('a3780000-0000-4000-8000-000000000001','MATRICIA_ADMIN');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b3780000-0000-4000-8000-000000000001','TEST378 catalogue','TEST378 catalogue','ACTIVE','a3780000-0000-4000-8000-000000000001');
insert into public.catalog_libraries(id,code,slug,steward_organization_id,created_by)values('c3780000-0000-4000-8000-000000000001','TEST378','test378','b3780000-0000-4000-8000-000000000001','a3780000-0000-4000-8000-000000000001'),('c3780000-0000-4000-8000-000000000002','TEST378_FOREIGN','test378-foreign','b3780000-0000-4000-8000-000000000001','a3780000-0000-4000-8000-000000000001');
insert into public.catalog_categories(id,library_id,code,slug,created_by)values('d3780000-0000-4000-8000-000000000001','c3780000-0000-4000-8000-000000000001','TEST378_CAT','test378-cat','a3780000-0000-4000-8000-000000000001'),('d3780000-0000-4000-8000-000000000002','c3780000-0000-4000-8000-000000000002','TEST378_FOREIGN_CAT','test378-foreign-cat','a3780000-0000-4000-8000-000000000001');
insert into public.catalog_subcategories(id,library_id,category_id,code,slug,created_by)values('e3780000-0000-4000-8000-000000000001','c3780000-0000-4000-8000-000000000001','d3780000-0000-4000-8000-000000000001','TEST378_SUB','test378-sub','a3780000-0000-4000-8000-000000000001'),('e3780000-0000-4000-8000-000000000002','c3780000-0000-4000-8000-000000000002','d3780000-0000-4000-8000-000000000002','TEST378_FOREIGN_SUB','test378-foreign-sub','a3780000-0000-4000-8000-000000000001');
insert into public.catalog_services(id,library_id,primary_subcategory_id,code,slug,status,created_by)values('f3780000-0000-4000-8000-000000000001','c3780000-0000-4000-8000-000000000001','e3780000-0000-4000-8000-000000000001','TEST378_SERVICE','test378-service','PUBLISHED','a3780000-0000-4000-8000-000000000001');
insert into public.catalog_service_versions(id,service_id,library_id,primary_subcategory_id,code,slug,version,status,name_fr,name_ar,short_description_fr,short_description_ar,long_description_fr,long_description_ar,service_type,unit_label_fr,unit_label_ar,sort_order,fulfillment_config,visibility_rules,change_reason,content_hash,sensitive,created_by,published_at)
values('f3781000-0000-4000-8000-000000000001','f3780000-0000-4000-8000-000000000001','c3780000-0000-4000-8000-000000000001','e3780000-0000-4000-8000-000000000001','TEST378_SERVICE','test378-service',1,'PUBLISHED','Service TEST378','خدمة اختبار378','Description courte TEST','وصف اختبار قصير','Description complète TEST','وصف اختبار كامل','ADVISORY','jour','يوم',1,'{"schema_version":1,"deliverables":["Legacy TEST content"]}','{"schema_version":1}','TEST initial legacy published metadata',repeat('a',64),true,'a3780000-0000-4000-8000-000000000001',clock_timestamp());
update public.catalog_services set current_published_version_id='f3781000-0000-4000-8000-000000000001'where id='f3780000-0000-4000-8000-000000000001';
create temporary table repair378(k text primary key,v jsonb);grant select,insert on repair378 to authenticated;grant usage on schema extensions to authenticated;
insert into repair378 select'published-before',to_jsonb(v)from public.catalog_service_versions v where id='f3781000-0000-4000-8000-000000000001';
create function pg_temp.save378(p_key text,p_source uuid default'f3781000-0000-4000-8000-000000000001',p_identity_version integer default 1,p_source_version integer default 1,p_parent uuid default'e3780000-0000-4000-8000-000000000001')returns jsonb language sql as $$
 select public.save_catalog_service_draft('f3780000-0000-4000-8000-000000000001',p_source,p_parent,'TEST378_SERVICE','test378-service','Service TEST378 édité','خدمة اختبار378 معدلة','Description courte TEST','وصف اختبار قصير','Description complète TEST','وصف اختبار كامل','ADVISORY','jour','يوم',false,false,false,false,true,false,'MAD',1,'{"schema_version":1,"deliverables":[{"label_fr":"Rapport TEST","label_ar":"تقرير اختبار"}]}','{"schema_version":1}',false,'TEST378 native same-parent save',p_identity_version,p_source_version,p_key)
$$;
select is((select count(*)from public.catalog_service_subcategory_links where service_id='f3780000-0000-4000-8000-000000000001'),0::bigint,'legacy source really lacks the required primary relation');
select set_config('request.jwt.claim.role','authenticated',true),set_config('request.jwt.claim.sub','a3780000-0000-4000-8000-000000000002',true),set_config('request.jwt.claims','{"sub":"a3780000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select throws_ok($$select pg_temp.save378('TEST378-foreign-actor')$$,'42501','CATALOG_SCOPE_DENIED','unauthorized actor cannot repair another catalogue');
reset role;
select set_config('request.jwt.claim.sub','a3780000-0000-4000-8000-000000000001',true),set_config('request.jwt.claims','{"sub":"a3780000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);set local role authenticated;
select throws_ok($$select pg_temp.save378('TEST378-old-sensitive-no-aal2')$$,'42501','CATALOG_SCOPE_DENIED','AAL1 is denied by the existing authority guard before any structural repair, even when the submitted sensitivity flag is false');
reset role;
select set_config('request.jwt.claims','{"sub":"a3780000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);set local role authenticated;
select throws_ok($$select pg_temp.save378('TEST378-foreign-parent','f3781000-0000-4000-8000-000000000001',1,1,'e3780000-0000-4000-8000-000000000002')$$,'23514','CATALOG_PARENT_SCOPE_MISMATCH','repair cannot move the parent into another library');
insert into repair378 values('saved',pg_temp.save378('TEST378-native-save'));
select is((select v->>'outcome'from repair378 where k='saved'),'CATALOG_SERVICE_DRAFT_SAVED','authorized real save opens the draft');
select is((select v->>'parent_changed'from repair378 where k='saved'),'false','the parent was not artificially changed to repair its relation');
select is((select v->>'primary_link_repaired'from repair378 where k='saved'),'true','receipt identifies the structural repair without certifying publication');
select is(pg_temp.save378('TEST378-native-save'),(select v from repair378 where k='saved'),'same request replays its exact committed receipt after the identity version advanced');
reset role;
select is((select count(*)from public.catalog_service_subcategory_links where service_id='f3780000-0000-4000-8000-000000000001'and subcategory_id='e3780000-0000-4000-8000-000000000001'and link_type='PRIMARY'and status='DRAFT'),1::bigint,'same-parent save creates exactly one native primary draft link');
select is((select count(*)from public.catalog_service_subcategory_link_versions v join public.catalog_service_subcategory_links l on l.id=v.link_id where l.service_id='f3780000-0000-4000-8000-000000000001'),1::bigint,'retry does not add duplicate primary versions');
select is((select to_jsonb(v)from public.catalog_service_versions v where id='f3781000-0000-4000-8000-000000000001'),(select v from repair378 where k='published-before'),'the full original published version is unchanged');
select ok((select status='PUBLISHED'and current_published_version_id='f3781000-0000-4000-8000-000000000001'and current_draft_version_id=(select(v->>'version_id')::uuid from repair378 where k='saved')from public.catalog_services where id='f3780000-0000-4000-8000-000000000001'),'published pointer and identity status are preserved while a separate draft is opened');
select ok((select status='DRAFT'and translation_review_status='PENDING'from public.catalog_service_versions where id=(select(v->>'version_id')::uuid from repair378 where k='saved')),'repair does not grant editorial or translation approval');
select ok((select metadata->>'primary_link_repaired'='true'and metadata->>'parent_changed'='false'from public.audit_events where action='catalog.service.draft_saved'and resource_id='f3780000-0000-4000-8000-000000000001'order by occurred_at desc limit 1),'the native audit identifies the same-parent repair');
select ok((select payload->>'primary_link_repaired'='true'from public.event_outbox where event_type='CatalogServiceDraftSavedV1'and aggregate_id='f3780000-0000-4000-8000-000000000001'order by occurred_at desc limit 1),'the normal native outbox carries structural repair metadata');
select is((select count(*)from public.audit_events where action='catalog.service.draft_saved'and resource_id='f3780000-0000-4000-8000-000000000001'),1::bigint,'replay did not manufacture a second audit effect');
set local role authenticated;
insert into repair378 select'saved-again',pg_temp.save378('TEST378-second-native-save',(v->>'version_id')::uuid,(v->>'identity_row_version')::integer,(v->>'version_row_version')::integer)from repair378 where k='saved';
select is((select v->>'primary_link_repaired'from repair378 where k='saved-again'),'false','an existing coherent primary relation is reused without another repair');
reset role;
select is((select count(*)from public.catalog_service_subcategory_link_versions v join public.catalog_service_subcategory_links l on l.id=v.link_id where l.service_id='f3780000-0000-4000-8000-000000000001'),1::bigint,'normal repeated edits do not duplicate a valid primary relation');
select is((select to_jsonb(v)from public.catalog_service_versions v where id='f3781000-0000-4000-8000-000000000001'),(select v from repair378 where k='published-before'),'later draft edits also preserve the original published history');
select ok(not has_function_privilege('anon','public.save_catalog_service_draft(uuid,uuid,uuid,text,text,text,text,text,text,text,text,text,text,text,boolean,boolean,boolean,boolean,boolean,boolean,text,integer,jsonb,jsonb,boolean,text,integer,integer,text,uuid)','execute')and not has_function_privilege('service_role','public.save_catalog_service_draft(uuid,uuid,uuid,text,text,text,text,text,text,text,text,text,text,text,boolean,boolean,boolean,boolean,boolean,boolean,text,integer,jsonb,jsonb,boolean,text,integer,integer,text,uuid)','execute'),'repair does not expose the native mutation to anonymous or service principals');
select *from finish();rollback;
